import {
  MeshBasicNodeMaterial,
  MeshStandardNodeMaterial
} from 'three/webgpu';
import {
  PlaneGeometry,
  BoxGeometry,
  CircleGeometry,
  Group,
  Mesh,
  Color
} from 'three/webgpu';
import {
  uv,
  texture,
  positionLocal,
  normalLocal,
  vec3,
  mix
} from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const root = new Group();
  const resources = [];
  const primitiveResults = [];
  const timelines = [];
  let disposed = false;

  const visualSpec = config.intent?.visualSpec ?? {};
  const colors = visualSpec.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10'
  };

  const ink = new Color(colors.ink);
  const paper = new Color(colors.paper);
  const accent = new Color(colors.accent);
  const surface = new Color(colors.surface);

  const makeVec3 = (value) => vec3(value.r, value.g, value.b);

  const stops = Array.isArray(visualSpec.gradientStops) && visualSpec.gradientStops.length
    ? visualSpec.gradientStops
    : [colors.surface, colors.ink, colors.primary ?? colors.ink];

  const stopColors = stops.map((stop) => {
    const value = typeof stop === 'string'
      ? stop
      : stop?.color ?? stop?.value ?? colors.surface;
    return makeVec3(new Color(value));
  });

  let backdropNode = stopColors[0];
  for (let i = 1; i < stopColors.length; i += 1) {
    const start = (i - 1) / Math.max(1, stopColors.length - 1);
    const end = i / Math.max(1, stopColors.length - 1);
    const localY = uv().y;
    const segment = localY.sub(start).div(end - start).clamp(0, 1);
    backdropNode = mix(backdropNode, stopColors[i], segment);
  }

  const backdropMaterial = new MeshBasicNodeMaterial({
    transparent: false
  });
  backdropMaterial.colorNode = backdropNode;

  const backdrop = new Mesh(
    new PlaneGeometry(7, 6, 1, 1),
    backdropMaterial
  );
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);
  resources.push(backdrop.geometry, backdrop.material);

  const shadowMaterial = new MeshBasicNodeMaterial({
    color: surface,
    transparent: true,
    opacity: 0.48,
    depthWrite: false
  });
  const shadow = new Mesh(
    new CircleGeometry(1.9, 48),
    shadowMaterial
  );
  shadow.scale.set(1.9, 0.36, 1);
  shadow.position.set(0, -0.76, -0.42);
  root.add(shadow);
  resources.push(shadow.geometry, shadow.material);

  const panelMaterial = new MeshStandardNodeMaterial({
    color: ink,
    roughness: 0.62,
    metalness: 0.48
  });
  const panel = new Mesh(
    new BoxGeometry(5.9, 1.18, 0.16),
    panelMaterial
  );
  panel.position.set(0, 0, 0);
  root.add(panel);
  resources.push(panel.geometry, panel.material);

  const imageMaterial = new MeshStandardNodeMaterial({
    color: paper,
    roughness: 0.58,
    metalness: 0.28
  });
  const imagePlane = new Mesh(
    new PlaneGeometry(5.72, 1.02, 64, 64),
    imageMaterial
  );
  imagePlane.position.set(0, 0, 0.105);
  root.add(imagePlane);
  resources.push(imagePlane.geometry, imagePlane.material);

  const accentMaterial = new MeshBasicNodeMaterial({
    color: accent,
    transparent: true,
    opacity: 0.92
  });
  const accentBar = new Mesh(
    new BoxGeometry(0.045, 0.88, 0.035),
    accentMaterial
  );
  accentBar.position.set(-2.72, 0, 0.2);
  root.add(accentBar);
  resources.push(accentBar.geometry, accentBar.material);

  const rimMaterial = new MeshStandardNodeMaterial({
    color: accent,
    emissive: accent,
    emissiveIntensity: 1.15,
    roughness: 0.56,
    metalness: 0.38
  });
  const rimBar = new Mesh(
    new BoxGeometry(5.35, 0.018, 0.028),
    rimMaterial
  );
  rimBar.position.set(0.1, -0.47, 0.2);
  root.add(rimBar);
  resources.push(rimBar.geometry, rimBar.material);

  const items = config.textContent ?? visualSpec.textContent ?? [];
  const textGroup = new Group();
  textGroup.position.set(-2.42, -0.01, 0.23);
  root.add(textGroup);

  const itemSpacing = 0.25;
  for (const item of items) {
    if (!item || typeof item.text !== 'string') continue;

    const role = item.role ?? 'body';
    const fontSize = item.typography?.fontSize
      ?? (role === 'hero' || role === 'headline' ? 0.34 : role === 'caption' ? 0.09 : 0.13);

    const textObject = ctx.fontAtlas.createText(item.text, {
      fontSize,
      color: role === 'caption' ? colors.accent : colors.paper,
      align: item.typography?.align ?? 'left',
      maxWidthPx: item.typography?.maxWidthPx,
      letterSpacingPx: item.typography?.letterSpacingPx
    });

    textObject.position.y = -(textGroup.children.length * itemSpacing);
    textGroup.add(textObject);
  }

  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      if (disposed) {
        tex.dispose?.();
        return;
      }
      resources.push(tex);
      imageMaterial.map = tex;
      imageMaterial.needsUpdate = true;
    });
  }

  if (config.depthMapUrl) {
    ctx.textureLoader.loadTexture(config.depthMapUrl).then((depthTex) => {
      if (disposed) {
        depthTex.dispose?.();
        return;
      }

      resources.push(depthTex);
      const depthNode = texture(depthTex);
      imagePlane.material.positionNode = positionLocal.add(
        normalLocal.mul(depthNode.r.mul(0.16))
      );
      imagePlane.material.needsUpdate = true;
    });
  }

  const entrance = gsap.timeline({ paused: true });
  entrance.fromTo(
    root.position,
    { y: 0.4 },
    { y: 0, duration: 0.7, ease: 'power3.out' }
  );
  entrance.fromTo(
    root.scale,
    { x: 1.04, y: 1.04, z: 1.04 },
    { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' },
    '<'
  );
  entrance.play();
  timelines.push(entrance);

  const primitiveList = config.cinematicPrimitives ?? [];
  for (const primitive of primitiveList) {
    if (!primitive?.name || typeof ctx.primitives?.[primitive.name] !== 'function') continue;
    const result = ctx.primitives[primitive.name](root, primitive.params ?? {});
    if (result) {
      primitiveResults.push(result);
      if (result.timeline) timelines.push(result.timeline);
    }
  }

  const hoverIn = () => {
    gsap.to(root.position, {
      y: 0.15,
      duration: 0.3,
      ease: 'power2.out',
      overwrite: true
    });
  };

  const hoverOut = () => {
    gsap.to(root.position, {
      y: 0,
      duration: 0.3,
      ease: 'power2.out',
      overwrite: true
    });
  };

  const click = () => {
    ctx.emit('hub-pricing.select', {
      node: config.id ?? config.nodeId ?? 'pricing-row'
    });
  };

  root.userData.handlers = {
    hover: (active = true) => {
      if (active === false) hoverOut();
      else hoverIn();
    },
    pointerenter: hoverIn,
    pointerleave: hoverOut,
    click
  };

  root.userData.dataBinding = {
    source: 'trpc.visits.book.slot',
    target: 'confirmPanel'
  };

  root.userData.cleanup = () => {
    if (disposed) return;
    disposed = true;

    for (const timeline of timelines) {
      timeline?.kill?.();
    }

    for (const result of primitiveResults) {
      result?.cleanup?.();
    }

    root.traverse((object) => {
      if (object.geometry) object.geometry.dispose?.();
      if (object.material) {
        if (Array.isArray(object.material)) {
          object.material.forEach((material) => material.dispose?.());
        } else {
          object.material.dispose?.();
        }
      }
    });

    for (const resource of resources) {
      resource?.dispose?.();
    }
  };

  return root;
}
